//! Golden parity tests against the Python engine.
//!
//! The expected values are generated by `tools/export_parity_data.py` from the
//! real Python engine and committed under `tests/data/`.  These tests are the
//! phase-1 migration gate: every EN↔RU decision the Python engine makes must be
//! reproduced exactly by the Rust port.

use std::path::PathBuf;

use ps_core::layout_set::{LayoutSet, DEFAULT_MIN_WORD_LEN, DEFAULT_THRESHOLD};
use ps_core::ngram::Prepared;
use serde::Deserialize;

fn repo_root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../..")
        .canonicalize()
        .expect("repo root")
}

fn profiles_dir() -> PathBuf {
    repo_root().join("power_switcher/detection/profiles")
}

fn layouts_json() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("data/layouts.json")
}

fn ls2() -> LayoutSet {
    LayoutSet::create(&["en", "ru"], &profiles_dir(), &layouts_json(), None)
        .expect("load en/ru set")
}

fn ls5() -> LayoutSet {
    LayoutSet::create(
        &["en", "ru", "ua", "de", "fr"],
        &profiles_dir(),
        &layouts_json(),
        None,
    )
    .expect("load 5-layout set")
}

#[derive(Deserialize)]
struct ScoreCase {
    word: String,
    lang: String,
    #[serde(default)]
    set: Option<u8>,
    score: f64,
    decision: f64,
}

#[derive(Deserialize)]
struct DecisionCase {
    word: String,
    cur: String,
    want: Option<String>,
    #[serde(default)]
    note: Option<String>,
}

fn load_cases<T: for<'de> Deserialize<'de>>(name: &str) -> Vec<T> {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests/data")
        .join(name);
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| {
        panic!(
            "missing parity data {path:?} — run `PYTHONPATH=. python3 tools/export_parity_data.py`: {e}"
        )
    });
    serde_json::from_str(&text).expect("parse parity data")
}

#[test]
fn score_parity_with_python() {
    let cases = load_cases::<ScoreCase>("parity_scores.json");
    let mut ls2_set = ls2();
    let mut ls5_set = ls5();
    let mut checked = 0usize;
    let mut max_diff = 0.0f64;

    for case in &cases {
        let ls = if case.set == Some(5) {
            &mut ls5_set
        } else {
            &mut ls2_set
        };
        let prepared = Prepared::new(&case.word);
        let got_score = ls.ngram_score_prepared(&prepared, &case.lang);
        let got_decision = ls.decision_score_prepared(&prepared, &case.lang);

        let d1 = (got_score - case.score).abs();
        let d2 = (got_decision - case.decision).abs();
        max_diff = max_diff.max(d1).max(d2);
        assert!(
            d1 <= 1e-9 && d2 <= 1e-9,
            "score mismatch for {:?} ({}): got score={got_score:.12}/decision={got_decision:.12}, \
             want score={:.12}/decision={:.12} (max diff so far {max_diff:e})",
            case.word,
            case.lang,
            case.score,
            case.decision
        );
        checked += 1;
    }
    println!("score parity: {checked} cases, max |diff| = {max_diff:e}");
    assert!(checked > 400, "expected a substantial corpus");
}

#[test]
fn decision_parity_en_ru() {
    let cases = load_cases::<DecisionCase>("parity_en_ru.json");
    let mut ls = ls2();

    let mut mismatches: Vec<String> = Vec::new();
    let mut conversions = 0usize;
    let mut keeps = 0usize;

    for case in &cases {
        let got = ls.find_best_layout(
            &case.word,
            &case.cur,
            DEFAULT_THRESHOLD,
            DEFAULT_MIN_WORD_LEN,
        );
        match (&got, &case.want) {
            (Some(g), Some(w)) if g == w => conversions += 1,
            (None, None) => keeps += 1,
            _ => {
                if mismatches.len() < 25 {
                    mismatches.push(format!(
                        "{:?} on {:?}: got {got:?}, want {:?}{}",
                        case.word,
                        case.cur,
                        case.want,
                        case.note
                            .as_deref()
                            .map(|n| format!(" ({n})"))
                            .unwrap_or_default()
                    ));
                }
            }
        }
    }

    println!(
        "decision parity: {} cases ({} conversions, {} keeps), {} mismatches",
        cases.len(),
        conversions,
        keeps,
        mismatches.len()
    );
    assert!(
        mismatches.is_empty(),
        "decision mismatches (showing up to 25 of {}):\n{}",
        cases.len(),
        mismatches.join("\n")
    );
    assert!(conversions > 5000, "expected many conversions");
}
